package proto

import (
	"bytes"
	"encoding/hex"
	"testing"
)

// Vectors generated by the original oneme_proto.py.
const pyPacket = "0a00000500130000001782a5746f6b656ea3616263aa6368617473436f756e740f"
const pyVCP = "46:8B97InRrbiI6ICJUIiwgInN0bmUiOiAic3R1bjphIiwgInRybnUiOiAiMTo5OSJ9"

func TestDecodePythonPacket(t *testing.T) {
	raw, _ := hex.DecodeString(pyPacket)
	p, err := DecodePacket(raw)
	if err != nil {
		t.Fatal(err)
	}
	m := p.Payload.(map[string]interface{})
	if p.Cmd != 0 || p.Seq != 5 || p.Opcode != 19 || m["token"] != "abc" {
		t.Fatalf("%+v", p)
	}
}

func TestEncodeMatchesPythonLayout(t *testing.T) {
	out, err := EncodePacket(0, 5, 19, map[string]interface{}{"token": "abc", "chatsCount": 15})
	if err != nil {
		t.Fatal(err)
	}
	// header must be byte-identical (map key order may differ in payload)
	raw, _ := hex.DecodeString(pyPacket)
	if !bytes.Equal(out[:10], raw[:10]) {
		t.Fatalf("header %x vs %x", out[:10], raw[:10])
	}
	if _, err := DecodePacket(out); err != nil {
		t.Fatal(err)
	}
}

func TestDecodeVCP(t *testing.T) {
	v, err := DecodeVCP(pyVCP)
	if err != nil || v["tkn"] != "T" || v["trnu"] != "1:99" {
		t.Fatalf("%v %v", v, err)
	}
}

func TestDecodePacketWithExt8MapKey(t *testing.T) {
	// Header: ver=10, cmd=1, seq=2, opcode=19, compRatio=0, len=14 (0x00000e)
	header := []byte{10, 1, 0, 2, 0, 19, 0, 0, 0, 14}
	// Payload: map of 1 element, key is ext8 (0xc7, len=5, type=1, data=[1,2,3,4,5]), val is fixstr "test"
	payload := []byte{0x81, 0xc7, 0x05, 0x01, 0x01, 0x02, 0x03, 0x04, 0x05, 0xa4, 't', 'e', 's', 't'}
	pktBytes := append(header, payload...)

	p, err := DecodePacket(pktBytes)
	if err != nil {
		t.Fatalf("DecodePacket failed: %v", err)
	}
	m, ok := p.Payload.(map[string]interface{})
	if !ok {
		t.Fatalf("expected map[string]interface{}, got %T", p.Payload)
	}
	if m["4328719365"] != "test" {
		t.Fatalf("unexpected map contents: %+v", m)
	}
}

func TestDecodePacketWithIntegerMapKey(t *testing.T) {
	// Header: ver=10, cmd=1, seq=2, opcode=19, compRatio=0, len=7
	header := []byte{10, 1, 0, 2, 0, 19, 0, 0, 0, 7}
	// Payload: map of 1 element: { 42: "answer" }
	payload := []byte{0x81, 42, 0xa6, 'a', 'n', 's', 'w', 'e', 'r'}
	header[9] = byte(len(payload))
	pktBytes := append(header, payload...)

	p, err := DecodePacket(pktBytes)
	if err != nil {
		t.Fatalf("DecodePacket failed: %v", err)
	}
	m, ok := p.Payload.(map[string]interface{})
	if !ok {
		t.Fatalf("expected map[string]interface{}, got %T", p.Payload)
	}
	if m["42"] != "answer" {
		t.Fatalf("unexpected map contents: %+v", m)
	}
}

func TestBigIntExtDecoding(t *testing.T) {
	ext := &BigIntExt{}
	// 8-byte big-endian representation of 86555706
	raw := []byte{0x00, 0x00, 0x00, 0x00, 0x05, 0x28, 0xbc, 0x3a}
	if err := ext.UnmarshalMsgpack(raw); err != nil {
		t.Fatalf("UnmarshalMsgpack failed: %v", err)
	}
	if ext.String() != "86555706" {
		t.Fatalf("expected string '86555706', got '%s'", ext.String())
	}
	if v, ok := ext.Value.(int64); !ok || v != 86555706 {
		t.Fatalf("expected int64 86555706, got %v (%T)", ext.Value, ext.Value)
	}
}
